head.script:
(function() {
  try {
    var saved = localStorage.getItem('mbare-theme');
    var sysDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
    var theme = saved ? saved : (sysDark ? 'dark' : 'light');
    document.documentElement.setAttribute('data-theme', theme);
  } catch(e) {}
})();

head.b:skin:
   /*-----------------------------------------------------------------------------
      Name:       	 M-StruX
      Version:    	 2.2.3
	  Release Date : 2026	
      Author:     	 matsusan
