(function() {
  if (window.__cfWidgetsLoaded) return;
  window.__cfWidgetsLoaded = true;
  var blogId = '<data:blog.blogId/>';
  var found = null;
  var all = document.querySelectorAll('script[src]');
  for (var i = 0; i < all.length; i++) {
    if (all[i].src.indexOf('widgets.js') !== -1) { found = all[i].src; break; }
  }
  var url = found || 'https://www.blogger.com/static/v1/widgets/widgets.js';
  var s = document.createElement('script');
  s.src = url;
  s.onload = function() {
    try {
      _WidgetManager._Init(
        'https://www.blogger.com/rearrange?blogID=' + blogId,
        '//' + window.location.hostname,
        blogId
      );
      window.__cfWidgetManagerReady = true;
      console.log('[CF] _WidgetManager ready');
    } catch(e) {
      console.warn('[CF] _Init failed:', e);
      window.__cfWidgetManagerReady = true;
    }
  };
  s.onerror = function() {
    console.warn('[CF] widgets.js load failed, url:', url);
    window.__cfWidgetManagerReady = true;
  };
  document.head.appendChild(s);
})();
